import {uid} from './blocks.js';
import {assetList,putAsset,removeAsset,SOUND_MIMES,MEDIA_BUDGET} from './assets.js';
import {createRecorder} from './recorder.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const dataURL=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('文件无法读取'));reader.readAsDataURL(blob);});
const imageFrom=data=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('图片无法读取'));image.src=data;});
export function createAssetEditor({getProject,onChange,isRunning,notice,audio}){
  const dialog=el('dialog','media-dialog');dialog.id='assetDialog';dialog.setAttribute('aria-label','自定义素材');document.body.append(dialog);
  let kind='sprites',token=0,draft=null,undo=[],painting=false,erasing=false,previous=null,processing=false;
  const heading=el('h2'),close=el('button','dialog-close','×');close.setAttribute('aria-label','关闭素材编辑');close.addEventListener('click',()=>dialog.close());
  const tabs=el('div','media-tabs'),list=el('div','asset-list'),workspace=el('div','asset-workspace'),status=el('p','media-status'),name=el('input');status.setAttribute('role','status');name.maxLength=40;name.setAttribute('aria-label','素材名称');
  const titleLabel=el('label','media-name','素材名称');titleLabel.append(name);
  for(const [key,label] of [['sprites','角色'],['backdrops','背景'],['sounds','声音']]){const btn=el('button','button secondary',label);btn.addEventListener('click',()=>open(key));btn.dataset.media=key;tabs.append(btn);}
  const canvas=el('canvas','paint-canvas');canvas.setAttribute('aria-label','素材画布');canvas.width=320;canvas.height=320;const ctx=canvas.getContext('2d');
  const color=el('input');color.type='color';color.value='#7555cd';color.setAttribute('aria-label','画笔颜色');const size=el('input');size.type='range';size.min=1;size.max=40;size.value=8;size.setAttribute('aria-label','画笔粗细');
  const paintTools=el('div','paint-tools'),pen=el('button','button secondary','画笔'),eraser=el('button','button secondary','橡皮'),clear=el('button','button secondary','清空画布'),undoBtn=el('button','button secondary','撤销笔画');
  pen.addEventListener('click',()=>{erasing=false;updateBrush();});eraser.addEventListener('click',()=>{erasing=true;updateBrush();});clear.addEventListener('click',()=>{snapshot();ctx.clearRect(0,0,canvas.width,canvas.height);});undoBtn.addEventListener('click',async()=>{const saved=undo.pop();if(!saved)return;const current=token;try{const image=await imageFrom(saved);if(current!==token)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);}catch(error){notice(error.message);}});paintTools.append(pen,eraser,color,size,undoBtn,clear);
  const file=el('input');file.type='file';file.hidden=true;file.setAttribute('aria-label','导入素材文件');
  const importBtn=el('button','button secondary','↑ 导入图片'),fresh=el('button','button secondary','＋ 新画作'),save=el('button','button primary','保存并使用');
  importBtn.addEventListener('click',()=>file.click());fresh.addEventListener('click',()=>resetDraft());
  const record=el('button','button record-button','● 开始录音'),stop=el('button','button secondary','■ 停止录音'),preview=el('button','button secondary','▶ 试听'),recordTools=el('div','record-tools');recordTools.append(record,stop,preview);
  const recorder=createRecorder({onState:phase=>{record.disabled=phase!=='idle'||processing;stop.disabled=!['requesting','recording'].includes(phase);save.disabled=phase!=='idle'||processing;if(phase==='requesting')status.textContent='正在请求麦克风权限…可取消';if(phase==='recording')status.textContent='正在录音，最长 30 秒。停止后可以试听和保存。';if(phase==='stopping')status.textContent='正在处理录音…';},onError:error=>{status.textContent=error.message;},onData:blob=>acceptSound(blob,'我的录音')});
  record.addEventListener('click',async()=>{const current=token;try{await audio.unlock();if(current===token)await recorder.start();}catch(error){status.textContent=error.message;}});stop.addEventListener('click',()=>recorder.stop());
  preview.addEventListener('click',async()=>{const current=token;try{audio.stop();await audio.unlock();if(current===token&&draft?.data)await audio.play({kind:'recording',data:draft.data,volume:80});}catch(error){if(current===token)status.textContent=error.message;}});
  const actions=el('div','media-actions');actions.append(importBtn,fresh,save);
  workspace.append(titleLabel,paintTools,canvas,recordTools,status,actions,file);dialog.append(close,el('div','eyebrow','MAKE IT YOUR OWN'),heading,tabs,list,workspace);
  function updateBrush(){pen.classList.toggle('selected',!erasing);eraser.classList.toggle('selected',erasing);}
  function snapshot(){undo.push(canvas.toDataURL());if(undo.length>20)undo.shift();}
  function point(e){const rect=canvas.getBoundingClientRect();return {x:(e.clientX-rect.left)*canvas.width/rect.width,y:(e.clientY-rect.top)*canvas.height/rect.height};}
  function stroke(a,b){ctx.save();ctx.globalCompositeOperation=erasing?'destination-out':'source-over';ctx.strokeStyle=color.value;ctx.fillStyle=color.value;ctx.lineWidth=Number(size.value);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.beginPath();ctx.arc(b.x,b.y,Number(size.value)/2,0,Math.PI*2);ctx.fill();ctx.restore();}
  canvas.addEventListener('pointerdown',e=>{if(processing)return;e.preventDefault();snapshot();painting=true;canvas.setPointerCapture(e.pointerId);previous=point(e);stroke(previous,previous);});canvas.addEventListener('pointermove',e=>{if(!painting)return;const next=point(e);stroke(previous,next);previous=next;});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>painting=false);
  function cleanup(){token++;recorder.cancel();audio.stop();painting=false;processing=false;}
  function resetDraft(){cleanup();draft=null;undo=[];name.value=kind==='sounds'?'我的录音':kind==='sprites'?'我的角色':'我的背景';canvas.width=kind==='backdrops'?480:320;canvas.height=kind==='backdrops'?360:320;ctx.clearRect(0,0,canvas.width,canvas.height);status.textContent=kind==='sounds'?'点击开始录音后才会请求麦克风权限。若大厅或浏览器不支持，可导入系统录音（最长 30 秒）。':'导入 PNG / JPEG / WebP，或直接在画布上画。角色支持透明底色。';preview.disabled=true;save.disabled=false;record.disabled=false;stop.disabled=true;updateBrush();}
  function renderList(){list.replaceChildren();for(const asset of assetList(getProject(),kind)){
    const card=el('div','asset-card');if(kind!=='sounds'){const image=el('img');image.src=asset.data;image.alt=asset.name;card.append(image);}card.append(el('strong','',asset.name));
    const edit=el('button','button secondary',kind==='sounds'?'试听 / 编辑':'编辑'),remove=el('button','text-button','删除');edit.setAttribute('aria-label','编辑素材'+asset.name);edit.addEventListener('click',async()=>{resetDraft();draft={...asset};name.value=asset.name;if(kind==='sounds'){preview.disabled=false;status.textContent=`声音 ${asset.seconds.toFixed(1)} 秒`;}else{const current=token;try{const image=await imageFrom(asset.data);if(current!==token)return;canvas.width=asset.width;canvas.height=asset.height;ctx.drawImage(image,0,0);}catch(error){status.textContent=error.message;}}});remove.setAttribute('aria-label','删除素材'+asset.name);remove.addEventListener('click',()=>{if(onChange(removeAsset(getProject(),kind,asset.id))){resetDraft();renderList();}});card.append(edit,remove);list.append(card);
  }}
  function open(nextKind='sprites'){if(isRunning())return;kind=nextKind;resetDraft();heading.textContent='自定义'+({sprites:'角色',backdrops:'背景',sounds:'声音'})[kind];for(const btn of tabs.children)btn.classList.toggle('selected',btn.dataset.media===kind);const sound=kind==='sounds';canvas.hidden=sound;paintTools.hidden=sound;recordTools.hidden=!sound;fresh.textContent=sound?'＋ 新录音':'＋ 新画作';importBtn.textContent=sound?'↑ 导入声音':'↑ 导入图片';file.accept=sound?'audio/webm,audio/ogg,audio/mp4,audio/mpeg,audio/wav,audio/x-wav':'image/png,image/jpeg,image/webp';renderList();if(!dialog.open)dialog.showModal();}
  async function acceptSound(blob,title){const current=token;processing=true;save.disabled=true;record.disabled=true;status.textContent='正在读取声音…';try{if(blob.size>MEDIA_BUDGET)throw new Error('声音文件过大，请缩短后重试');const data=await dataURL(blob);if(current!==token)return;const seconds=await audio.inspect(data);if(current!==token)return;draft={id:'asset-'+uid(),name:title,data,seconds};name.value=title;preview.disabled=false;status.textContent=`声音已就绪：${seconds.toFixed(1)} 秒，可以试听后保存。`;}catch(error){if(current===token)status.textContent=error.message;}finally{if(current===token){processing=false;save.disabled=false;record.disabled=false;}}}
  file.addEventListener('change',async()=>{const selected=file.files[0];file.value='';if(!selected)return;const current=token;try{if(kind==='sounds'){if(!SOUND_MIMES.includes(selected.type.split(';')[0]))throw new Error('请选择 WebM / Ogg / MP4 / MP3 / WAV 声音');await acceptSound(selected,selected.name.replace(/\.[^.]+$/,'').slice(0,40));return;}if(!['image/png','image/jpeg','image/webp'].includes(selected.type)||selected.size>8*1024*1024)throw new Error('请选择 8 MB 以内的 PNG / JPEG / WebP 图片');const image=await imageFrom(await dataURL(selected));if(current!==token)return;const scale=Math.min(1,960/Math.max(image.width,image.height));canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));ctx.drawImage(image,0,0,canvas.width,canvas.height);draft=null;undo=[];name.value=selected.name.replace(/\.[^.]+$/,'').slice(0,40);status.textContent='图片已载入，可继续绘画或保存使用。';}catch(error){if(current===token)status.textContent=error.message;}});
  save.addEventListener('click',()=>{if(processing||recorder.phase!=='idle')return;if(kind==='sounds'&&!draft){status.textContent='请先录音或导入声音';return;}const asset={...(kind==='sounds'?draft:{id:draft?.id||'asset-'+uid(),data:canvas.toDataURL('image/png'),width:canvas.width,height:canvas.height}),name:name.value};let next=putAsset(getProject(),kind,asset);if(kind==='sprites')next.sprite=asset.id;if(kind==='backdrops')next.backdrop=asset.id;if(onChange(next)){notice('已保存'+asset.name);draft=asset;renderList();status.textContent='已保存到作品中；可以关闭窗口继续编程。';}});
  dialog.addEventListener('close',cleanup);window.addEventListener('pagehide',cleanup);document.addEventListener('visibilitychange',()=>{if(document.hidden)cleanup();});
  return {open,cancel:cleanup};
}
